import {readOpeningReview} from './invoice-opening-review';
type Scope={tenant:string;property:string;reservation:string;actor:string};
type Line={source_key:string;amount_minor:string};
export function prepareOpeningItemization(scope:Scope,request:string,options:unknown,input:{reversal:string;lines:Line[];reason:string}){
 const uuid=/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;if(![...Object.values(scope),request,input.reversal].every(v=>uuid.test(v)))throw Error('Invalid correction workspace.');
 const review=readOpeningReview(options,scope),reversal=review.reversals.find(r=>r.id===input.reversal);if(!reversal||reversal.itemized)throw Error('Select an unitemized opening reversal.');
 const reason=input.reason.trim();if(reason.length<4||reason.length>500||Array.from(reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127))throw Error('Enter a correction reason between 4 and 500 characters.');
 if(!Array.isArray(input.lines)||!input.lines.length||input.lines.length>100)throw Error('Select correction categories.');let total=BigInt(0);const seen=new Set<string>();
 const lines=input.lines.map(l=>{if(!l||typeof l.amount_minor!=='string'||!/^[1-9][0-9]{0,11}$/.test(l.amount_minor)||seen.has(l.source_key))throw Error('Invalid correction amount or duplicate category.');const source=review.lines.find(s=>s.source_key===l.source_key);if(!source||BigInt(l.amount_minor)>BigInt(source.available_minor))throw Error('Correction exceeds remaining category amount.');seen.add(l.source_key);total+=BigInt(l.amount_minor);return {source_key:l.source_key,amount_minor:l.amount_minor};});
 if(total.toString()!==reversal.amount_minor)throw Error('Category amounts must equal the reversal total.');
 return {actor:scope.actor,amount_minor:total.toString(),args:{p_tenant:scope.tenant,p_property:scope.property,p_reservation:scope.reservation,p_reversal:input.reversal,p_request:request,p_lines:lines,p_reason:reason,p_confirmed:true}};
}
export function readOpeningItemizationReceipt(value:unknown,request:ReturnType<typeof prepareOpeningItemization>){const r=value as Record<string,unknown>,a=request.args;if(!r||r.schema_version!==1||r.tenant_id!==a.p_tenant||r.property_id!==a.p_property||r.reservation_id!==a.p_reservation||r.actor_id!==request.actor||r.request_id!==a.p_request||r.reversal_id!==a.p_reversal||r.reason!==a.p_reason||typeof r.replayed!=='boolean'||!Array.isArray(r.lines)||r.lines.length!==a.p_lines.length)throw Error('Correction receipt does not match the reviewed request.');for(let i=0;i<a.p_lines.length;i++){const l=r.lines[i] as Record<string,unknown>;if(!l||l.source_key!==a.p_lines[i].source_key||l.amount_minor!==a.p_lines[i].amount_minor)throw Error('Correction receipt itemization changed.');}return {request_id:a.p_request,reversal_id:a.p_reversal,replayed:r.replayed};}

export function readOpeningItemizationStatus(value:unknown,request:ReturnType<typeof prepareOpeningItemization>){const r=value as Record<string,unknown>,a=request.args;if(!r||r.schema_version!==1||r.tenant_id!==a.p_tenant||r.property_id!==a.p_property||r.actor_id!==request.actor||r.request_id!==a.p_request||typeof r.found!=='boolean')throw Error('Correction recovery scope changed.');if(!r.found){if(r.result!==null)throw Error('Invalid correction recovery response.');return null;}return readOpeningItemizationReceipt(r.result,request);}

type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function key(scope:Scope){if(!Object.values(scope).every(v=>/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v)))throw Error('Invalid saved correction workspace.');return 'irp.opening.itemization.v1:'+ [scope.tenant,scope.property,scope.reservation,scope.actor].join(':');}
function savedRequest(value:unknown,scope:Scope):ReturnType<typeof prepareOpeningItemization>{
 const r=value as ReturnType<typeof prepareOpeningItemization>,a=r?.args,uuid=/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;
 if(!a||r.actor!==scope.actor||a.p_tenant!==scope.tenant||a.p_property!==scope.property||a.p_reservation!==scope.reservation||typeof a.p_request!=='string'||!uuid.test(a.p_request)||typeof a.p_reversal!=='string'||!uuid.test(a.p_reversal)||a.p_confirmed!==true||typeof a.p_reason!=='string'||a.p_reason!==a.p_reason.trim()||a.p_reason.length<4||a.p_reason.length>500||Array.from(a.p_reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)||!Array.isArray(a.p_lines)||!a.p_lines.length||a.p_lines.length>100)throw Error('Invalid saved correction. Preserve it for recovery.');
 const seen=new Set<string>();let total=BigInt(0);const lines=a.p_lines.map(l=>{if(!l||typeof l.source_key!=='string'||!l.source_key.startsWith('opening:')||l.source_key.length>500||seen.has(l.source_key)||typeof l.amount_minor!=='string'||!/^[1-9][0-9]{0,11}$/.test(l.amount_minor))throw Error('Invalid saved correction category.');seen.add(l.source_key);total+=BigInt(l.amount_minor);return {source_key:l.source_key,amount_minor:l.amount_minor};});if(total>BigInt('999999999999')||total.toString()!==r.amount_minor)throw Error('Saved correction total does not reconcile.');
 return {actor:scope.actor,amount_minor:r.amount_minor,args:{p_tenant:scope.tenant,p_property:scope.property,p_reservation:scope.reservation,p_reversal:a.p_reversal,p_request:a.p_request,p_lines:lines,p_reason:a.p_reason,p_confirmed:true}};
}
export function loadPendingOpening(store:Store,scope:Scope){const raw=store.getItem(key(scope));return raw===null?null:savedRequest(JSON.parse(raw),scope);}
export function savePendingOpening(store:Store,scope:Scope,request:ReturnType<typeof prepareOpeningItemization>){const saved=savedRequest(request,scope),existing=loadPendingOpening(store,scope),encoded=JSON.stringify(saved);if(existing&&JSON.stringify(existing)!==encoded)throw Error('Resolve the existing correction request first.');store.setItem(key(scope),encoded);if(store.getItem(key(scope))!==encoded)throw Error('Unable to preserve correction request.');return saved;}
export function clearPendingOpening(store:Store,scope:Scope,request:string){const existing=loadPendingOpening(store,scope);if(existing&&existing.args.p_request!==request)throw Error('A different correction is pending.');store.removeItem(key(scope));if(store.getItem(key(scope))!==null)throw Error('Unable to clear saved correction.');}
